package net.minecraft.client.gui.components;import net.minecraft.network.chat.Component;public class Button{public interface OnPress{void onPress(Button b);}public Component label;public OnPress press;public int x,y,width,height;public boolean active=true;public static Builder builder(Component c,OnPress p){return new Builder(c,p);}public static class Builder{Button b=new Button();Builder(Component c,OnPress p){b.label=c;b.press=p;}public Builder bounds(int x,int y,int w,int h){b.x=x;b.y=y;b.width=w;b.height=h;return this;}public Button build(){return b;}}}